package org.skillbridge.email;

import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Map;

/**
 * Renders email templates from classpath:/templates/email/*.
 *
 * Templates use simple ${placeholder} substitution — no engine required.
 * This keeps dependencies minimal and avoids any template-injection surface:
 * all substituted values are HTML-escaped by the caller before reaching here
 * (or are URLs generated by us).
 */
@Service
public class EmailRenderService {

    private static final String TEMPLATE_DIR = "templates/email/";

    public String renderVerifyEmailHtml(VerificationEmailPayload p) {
        return render("verify-email.html", Map.of(
                "recipientFirstName", escapeHtml(p.recipientFirstName()),
                "recipientEmail",     escapeHtml(p.recipientEmail()),
                "verifyUrl",          p.verifyUrl(),
                "expiresInHours",     String.valueOf(p.expiresInHours())
        ));
    }

    public String renderVerifyEmailText(VerificationEmailPayload p) {
        return render("verify-email.txt", Map.of(
                "recipientFirstName", p.recipientFirstName(),
                "recipientEmail",     p.recipientEmail(),
                "verifyUrl",          p.verifyUrl(),
                "expiresInHours",     String.valueOf(p.expiresInHours())
        ));
    }

    private String render(String filename, Map<String, String> vars) {
        String template = read(TEMPLATE_DIR + filename);
        String out = template;
        for (Map.Entry<String, String> e : vars.entrySet()) {
            out = out.replace("${" + e.getKey() + "}", e.getValue());
        }
        return out;
    }

    private String read(String path) {
        try (InputStream in = new ClassPathResource(path).getInputStream()) {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new IllegalStateException("Email template not found: " + path, e);
        }
    }

    private static String escapeHtml(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;");
    }
}
